var t=[{title:`Miért fontos az alvás az edzéshez`,text:`Az alvás segíti a szövetek helyreállítását, az idegrendszer működését, a figyelmet és a mozgáskészségek tanulását. Rossz alvás után egy szokásos terhelés nehezebbnek érződhet, és a motivációd vagy a koordinációd csökkenhet. Egyetlen rövid éjszaka nem törli el a fejlődésedet, de az alvás ismételt lerövidítése ronthatja az edzésed minőségét és az általános egészségedet.`},{title:`Hossz és minőség`,text:`A közegészségügyi irányelvek a 18–60 éves felnőtteknek hét vagy több órát ajánlanak, ezután korspecifikus tartományokkal. A gyakori ébredés, a szabálytalan napirend vagy a kipihentség hiánya akkor is számíthat, ha az ágyban töltött időd elég hosszúnak tűnik. Az igények eltérnek, ezért a megfelelő mennyiség egyéni.`},{title:`Segítő szokások`,text:`Elég következetes időpontban feküdj le és kelj fel, tartsd a hálószobát sötéten és kényelmesen, korlátozd a fényes világítást lefekvés előtt, és figyelj a késői koffeinre. A nappali fény és a rendszeres mozgás segíthet kiszámíthatóan tartani az alvásritmusodat. Ne ítéld meg az alvásodat egyetlen viselhető eszköz pontszáma alapján.`},{title:`Edzés egy rossz éjszaka után`,text:`Egy különösen rossz éjszaka után, ha az egyensúlyod vagy a koncentrációd nincs rendben, fontold meg egy könnyebb technikai edzést, egy könnyű sétát vagy egy kisebb edzést. Egy alkalmi nehéz nap önmagában nem veszélyes, de ha ismételten kimerülten erőltetsz maximális emeléseket, az nem tesz jót. Az alvásmérők becsléseket adnak, nem klinikai méréseket. Ha tartósan erős álmosságod vagy álmatlanságod van, beszélj orvosoddal.`}];var a=[{label:`CDC: alvásajánlások felnőtteknek`,url:`https://www.cdc.gov/sleep/about/index.html/`},{label:`2026-os ACSM: edzésadag, regeneráció és progresszió`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:t,sources:a};export{n as default,t as sections,a as sources};